import{_ as p,a0 as a,w as r,s as d,ao as l,I as i,x as o,a1 as n,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse('{"title":"如何在 Win8 上禁用 UEFI 以安装Linux | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Win8 上禁用 UEFI 以安装Linux | LCTT (201405) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Win8 上禁用 UEFI 以安装Linux | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Win8 上禁用 UEFI 以安装Linux | LCTT (201405) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201405/How To Disable UEFI Secure Boot In Windows 8 & 8.1","title":"如何在 Win8 上禁用 UEFI 以安装Linux","tag":"201405","desc":""},"relativePath":"201405/How To Disable UEFI Secure Boot In Windows 8 & 8.1.md","filePath":"[post].md"}'),u={name:"201405/How To Disable UEFI Secure Boot In Windows 8 & 8.1.md"};function w(g,t,m,f,I,W){const s=a("Link");return r(),d("div",null,[t[11]||(t[11]=l('<h1 id="如何在-win8-上禁用-uefi-以安装linux" tabindex="-1">如何在 Win8 上禁用 UEFI 以安装Linux <a class="header-anchor" href="#如何在-win8-上禁用-uefi-以安装linux" aria-label="Permalink to “如何在 Win8 上禁用 UEFI 以安装Linux”">​</a></h1><p><img src="http://itsfoss.com/wp-content/uploads/2014/05/Disable_Secure_Boot_Windows8_UEFI.jpeg" alt=""></p><p>现在，如果你买了预装 Windows 的电脑，一般都是 Windows8 或 Windows8.1。从 Windows8 开始，微软用 UEFI 取代了 BIOS。尽管 UEFI 不是微软发明的，在 Windows8 之前它就已经存在。比如某些 Mac 设备使用 UEFI 已经有一段时间了。</p><p>UEFI 有“安全启动”这个特点，引导程序只会启动那些得到 UEFI 固件签署的引导装载程序。此安全功能可以防止 Rootkit 类的恶意软件，并提供了额外的安全层。但它有一个缺点，如果你想在 Win8的电脑上双引导 Linux ，安全机制会阻止这样做。这篇文章告诉大家如何在Win8中禁用UEFI安全引导，以支持 Linux 的双系统启动。</p><h3 id="在windows-8-8-1上禁用uefi安全启动" tabindex="-1">在Windows 8 &amp; 8.1上禁用UEFI安全启动 <a class="header-anchor" href="#在windows-8-8-1上禁用uefi安全启动" aria-label="Permalink to “在Windows 8 &amp; 8.1上禁用UEFI安全启动”">​</a></h3><p>关于安全启动，充斥着各种各样的说法。由于这些传闻，有些人几乎认为在预装 Windows8 的电脑上启动 Linux 是不可能的。虽然在 ARM PC上这是真的，但是在基于 Intel 的系统上安全引导是可以被禁用的。老实说，<strong>禁用UEFI安全启动</strong>不是一个艰巨的任务，同样的双启动的 Linux 与 Windows 8 也不是。</p><p>虽然在 BIOS 时代，访问 BIOS 是相当简单的，在启动的时候按 F10 或 F12 键即可。但是在 UEFI 的世界里，就不一样了。要访问 UEFI 设置，你就必须进入到 Windows 中去。让我们来看看如何在 Windows 8 中访问 UEFI 设置来禁用安全启动。</p><h4 id="step-1-进入pc设置" tabindex="-1">Step 1: 进入PC设置 <a class="header-anchor" href="#step-1-进入pc设置" aria-label="Permalink to “Step 1: 进入PC设置”">​</a></h4><p>点击 Windows+I 按钮进入 Windows 设置界面。在底部，你会看到更改电脑设置的选项。点击它。</p><p><img src="http://itsfoss.com/wp-content/uploads/2014/05/Disable_Secure_Boot_1.jpeg" alt=""></p><h4 id="step-2-进入高级启动" tabindex="-1">Step 2: 进入高级启动 <a class="header-anchor" href="#step-2-进入高级启动" aria-label="Permalink to “Step 2: 进入高级启动”">​</a></h4><p>在 Windows 8 和 Windows8.1 上，PC设置有一个细微的差别。依照你使用的系统不同，分别按照下面介绍的各个步骤进行操作：</p><p>Windows 8的：在Windows 8中，你需要进入通用PC设置，并选择<strong>高级启动</strong>，然后点击<strong>立即重新启动：</strong></p><p><img src="http://itsfoss.com/wp-content/uploads/2014/05/Change_PC_Settings_Windows8.jpg" alt=""></p><p><strong>Window 8.1</strong>的：在 Windows8.1，从左侧边栏点击<strong>更新和恢复</strong>：</p><p><img src="http://itsfoss.com/wp-content/uploads/2014/05/Disable_Secure_Boot_Windows8_2.jpeg" alt=""></p><p>然后单击<strong>立即重新启动</strong>下的<strong>高级启动</strong>：</p><p><img src="http://itsfoss.com/wp-content/uploads/2014/05/Disable_Secure_Boot_Windows8_3.jpeg" alt=""></p><p>不要担心！这之后并不会立刻重新启动，而是会在下一步看到一些选项。</p><h4 id="step-4-进入uefi设置" tabindex="-1">Step 4: 进入UEFI设置 <a class="header-anchor" href="#step-4-进入uefi设置" aria-label="Permalink to “Step 4: 进入UEFI设置”">​</a></h4><p>当您单击了立即重新启动按钮，在下一页屏幕中，你将会看到一些可以选择的选项。这里选择<strong>疑难解答</strong>：</p><p><img src="http://itsfoss.com/wp-content/uploads/2014/05/Troubleshoot_Windows8.jpg" alt=""></p><p>在<strong>疑难解答</strong>菜单中，选择<strong>高级选项</strong>：</p><p><img src="http://itsfoss.com/wp-content/uploads/2014/05/Troubleshoot_Windows8_1.jpg" alt=""></p><p>在高级选项菜单中，选择<strong>UEFI固件设置</strong>：</p><p><img src="http://itsfoss.com/wp-content/uploads/2014/05/Troubleshoot_Windows8_2.jpg" alt=""></p><p>接下来，在UEFI设置里，点击<strong>重新启动</strong>按钮重新启动您的系统，就会看到类似BIOS一样的界面。</p><p><img src="http://itsfoss.com/wp-content/uploads/2014/05/Troubleshoot_Windows8_3.jpg" alt=""></p><h4 id="step-5-在-uefi-中禁用安全启动" tabindex="-1">Step 5: 在 UEFI 中禁用安全启动 <a class="header-anchor" href="#step-5-在-uefi-中禁用安全启动" aria-label="Permalink to “Step 5: 在 UEFI 中禁用安全启动”">​</a></h4><p>这个时候，你一定已经启动到 UEFI 工具界面。你可以在这里更改各种设置。但我们想要做的，只是禁用安全启动选项，允许 Ubuntu 或者任何其它 Linux 版本的双启动。</p><p>移动到启动选项卡，在那里你会发现<strong>安全引导</strong>选项被设置为启用。使用箭头键进入安全引导选项，然后按<strong>回车键</strong>来选择它。 <em>使用+或 - 来改变它的值。按</em>* F10 键保存更改<strong>并退出 UEFI 设置。</strong>提示时确认即可**。</p><p><img src="http://itsfoss.com/wp-content/uploads/2014/05/Disable_Secure_Boot_Windows8.jpg" alt=""></p><p>接下来，您将会正常引导到 Windows。现在，您就支持双启动 Windows8 与 Ubuntu 或其它 Linux 操作系统了。过段时间里我会写关于如何双启动 Ubuntu 与 Windows 8 UEFI 的教程。敬请关注。</p><p>我希望这个教程可以帮助您禁用 Windows8 和 Windows8.1 的安全引导。如有任何疑问或建议，欢迎随时评论。</p><hr>',35)),i("p",null,[t[1]||(t[1]=o("via: ",-1)),n(s,{href:"http://itsfoss.com/disable-uefi-secure-boot-in-windows-8/"},{default:e(()=>[...t[0]||(t[0]=[o("http://itsfoss.com/disable-uefi-secure-boot-in-windows-8/",-1)])]),_:1})]),i("p",null,[t[4]||(t[4]=o("译者：",-1)),n(s,{href:"https://github.com/MikeCoder"},{default:e(()=>[...t[2]||(t[2]=[o("MikeCoder",-1)])]),_:1}),t[5]||(t[5]=o(" 校对：",-1)),n(s,{href:"https://github.com/carolinewuyan"},{default:e(()=>[...t[3]||(t[3]=[o("Caroline",-1)])]),_:1})]),i("p",null,[t[8]||(t[8]=o("本文由 ",-1)),n(s,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[6]||(t[6]=[o("LCTT",-1)])]),_:1}),t[9]||(t[9]=o(" 原创翻译，",-1)),n(s,{href:"http://linux.cn/"},{default:e(()=>[...t[7]||(t[7]=[o("Linux中国",-1)])]),_:1}),t[10]||(t[10]=o(" 荣誉推出",-1))])])}const F=p(u,[["render",w]]);export{h as __pageData,F as default};
